goog.provide('glift.dom.ux');

/**
 * Модуль UX содержит утилиты для пользовательского интерфейса.
 * 
 * @module dom/ux
 */

/**
 * Определяет положение элемента относительно страницы.
 * @param {Element|string} element - DOM-элемент или его ID
 * @return {Object} Объект с координатами {top, left, bottom, right}
 */
export const offset = (element) => {
  const el = typeof element === 'string' ? document.getElementById(element) : element;
  
  if (!el) {
    console.error('Не удалось найти элемент для определения позиции:', element);
    return { top: 0, left: 0, bottom: 0, right: 0 };
  }
  
  const rect = el.getBoundingClientRect();
  const scrollLeft = window.pageXOffset || document.documentElement.scrollLeft;
  const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
  
  return {
    top: rect.top + scrollTop,
    left: rect.left + scrollLeft,
    bottom: rect.bottom + scrollTop,
    right: rect.right + scrollLeft
  };
};

/**
 * Определяет размеры окна просмотра.
 * @return {Object} Объект с размерами окна {width, height}
 */
export const viewport = () => {
  return {
    width: window.innerWidth,
    height: window.innerHeight
  };
};

/**
 * Определяет, отображается ли элемент в области видимости.
 * @param {Element|string} element - DOM-элемент или его ID
 * @return {boolean} true, если элемент видим
 */
export const isVisible = (element) => {
  const el = typeof element === 'string' ? document.getElementById(element) : element;
  
  if (!el) {
    return false;
  }
  
  const rect = el.getBoundingClientRect();
  const win = viewport();
  
  return (
    rect.top >= 0 &&
    rect.left >= 0 &&
    rect.bottom <= win.height &&
    rect.right <= win.width
  );
};

/**
 * Прокручивает страницу к элементу.
 * @param {Element|string} element - DOM-элемент или его ID
 * @param {boolean} smooth - Использовать плавную прокрутку
 */
export const scrollToElement = (element, smooth = true) => {
  const el = typeof element === 'string' ? document.getElementById(element) : element;
  
  if (!el) {
    console.error('Не удалось найти элемент для прокрутки:', element);
    return;
  }
  
  el.scrollIntoView({
    behavior: smooth ? 'smooth' : 'auto',
    block: 'center'
  });
};

/**
 * Возвращает информацию о событии касания или мыши.
 * @param {Event} event - Событие
 * @return {Object} Объект с координатами {x, y}
 */
export const getEventPosition = (event) => {
  // Если это касание
  if (event.touches && event.touches.length) {
    return {
      x: event.touches[0].pageX,
      y: event.touches[0].pageY
    };
  }
  
  // Если это мышь
  return {
    x: event.pageX,
    y: event.pageY
  };
};

/**
 * Служебные методы для улучшения пользовательского опыта.
 * Примечание по шаблонам свойств производителей:
 *   - -webkit-property => webkitProperty
 *   - -moz-property => MozProperty
 *   - -ms-property => msProperty
 *   - -o-property => OProperty
 *   - property => property
 * 
 * @namespace
 */
glift.dom.ux = {
  /**
   * Делает элемент невыделяемым, что полезно для элементов интерфейса
   * и игровых компонентов.
   * 
   * @param {string|!Element|!glift.dom.Element} id ID элемента, DOM элемент или glift элемент
   * @return {!glift.dom.Element} Измененный элемент
   */
  setNotSelectable(id) {
    const elem = typeof id === 'string' || (id && id.nodeType) 
      ? glift.dom.elem(id) 
      : id;
      
    return elem.css({
      webkitTouchCallout: 'none',
      webkitUserSelect: 'none',
      MozUserSelect: 'none',
      msUserSelect: 'none',
      userSelect: 'none',
      webkitHighlight: 'none',
      webkitTapHighlightColor: 'rgba(0,0,0,0)',
      cursor: 'default',
      outline: 'none'
    });
  },
  
  /**
   * Делает элемент кликабельным, применяя стили для лучшего UX.
   * 
   * @param {string|!Element|!glift.dom.Element} id ID элемента, DOM элемент или glift элемент
   * @return {!glift.dom.Element} Измененный элемент
   */
  setClickable(id) {
    const elem = typeof id === 'string' || (id && id.nodeType) 
      ? glift.dom.elem(id) 
      : id;
      
    return elem.css({
      cursor: 'pointer',
      webkitTapHighlightColor: 'rgba(0,0,0,0.3)'
    });
  },
  
  /**
   * Добавляет плавные переходы для изменений CSS свойств элемента.
   * 
   * @param {string|!Element|!glift.dom.Element} id ID элемента, DOM элемент или glift элемент
   * @param {string=} properties Свойства для анимации (по умолчанию "all")
   * @param {string=} duration Продолжительность анимации (по умолчанию "0.2s")
   * @param {string=} timingFunction Функция времени (по умолчанию "ease")
   * @return {!glift.dom.Element} Измененный элемент
   */
  setTransition(id, properties = 'all', duration = '0.2s', timingFunction = 'ease') {
    const elem = typeof id === 'string' || (id && id.nodeType) 
      ? glift.dom.elem(id) 
      : id;
    
    const transitionValue = `${properties} ${duration} ${timingFunction}`;
    
    return elem.css({
      webkitTransition: transitionValue,
      MozTransition: transitionValue,
      msTransition: transitionValue,
      OTransition: transitionValue,
      transition: transitionValue
    });
  },
  
  /**
   * Применяет стили, чтобы скрыть элемент при сохранении места в DOM.
   * 
   * @param {string|!Element|!glift.dom.Element} id ID элемента, DOM элемент или glift элемент
   * @param {boolean=} hide Скрыть или показать элемент (по умолчанию true - скрыть)
   * @return {!glift.dom.Element} Измененный элемент
   */
  setVisibility(id, hide = true) {
    const elem = typeof id === 'string' || (id && id.nodeType) 
      ? glift.dom.elem(id) 
      : id;
      
    return elem.css({
      visibility: hide ? 'hidden' : 'visible'
    });
  }
};
