/**
 * Модуль для работы с SVG элементами.
 * 
 * @module svg
 */

import { Element } from '../dom/dom.js';

/**
 * Создает SVG элемент с заданными атрибутами.
 * @param {Object} attrObj Объект с атрибутами для SVG элемента
 * @return {Object} SVG объект
 */
export const svg = (attrObj) => {
  const el = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  const svgObj = new SvgElement(el);
  
  if (attrObj) {
    svgObj.setAttr(attrObj);
  }
  
  return svgObj;
};

/**
 * Создает группу SVG элементов.
 * @return {Object} SVG группа
 */
export const group = () => {
  const el = document.createElementNS('http://www.w3.org/2000/svg', 'g');
  return new SvgElement(el);
};

